action.command:
cd /workspace && docker compose exec -T backend node -e '
const get = async (url) => {
  try {
    const r = await fetch(url, { redirect: "manual" });
    const body = await r.text();
    console.log(r.status, url, "len:", body.length, "title:", (body.match(/<title>(.*?)<\/title>/)||[])[1]);
  } catch (e) { console.log("ERR", url, e.message); }
};
(async () => {
  await get("http://dashboard:3000/");
  await get("http://dashboard:3000/eckener-schule/login");
  await get("http://dashboard:3000/eckener-schule");
})();
'

